INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (417862, 16336, 'NBC News', 'en', 'Tate brothers ask judge to be released from Miami jail as they fight extradition to U.K.', 'https://www.nbcnews.com/video/tate-brothers-ask-judge-to-be-released-from-miami-jail-as-they-fight-extradition-to-u-k-268974661975', '"Manosphere" influencers Andrew and Tristan Tate, who are facing rape and sex trafficking charges, asked a judge in Miami to be released from jail as they fight extradition to the U.K. After Andrew Tate took the witness stand, he denied being a rapist or human trafficker and described the proceedings as his “last chance.”', 'https://prodamdnewsencoding.akamaized.net/NBC_News_Digital/now_hallie_tate_brothers_miami_260827/1/abs/index.m3u8', '2026-08-27T22:24:26+00:00', '2026-08-28T00:05:54.237517'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
