INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (422725, 16336, 'France 24', 'en', 'US : Tate brothers remain in jail as judge delays bail decision', 'https://www.france24.com/en/us-tate-brothers-remain-in-jail-as-judge-delays-bail-decision', 'Andrew and Tristan Tate will remain in custody in Miami after a federal judge declined to rule on their bail request as they fight extradition to the UK, where they face charges including rape, assault, human trafficking and money laundering. The UK has until mid-September to submit its evidence to the US State Department, while the brothers continue to deny wrongdoing and claim their online personas were fictional.', 'https://s.france24.com/media/display/b13ff79a-a2b9-11f1-8c8c-005056a90284/w:1024/p:16x9/EN-20260828-070940-071105-CS.jpg', '2026-08-28T09:10:00+00:00', '2026-08-28T12:49:23.881512'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
