INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (427233, 16336, 'BBC News', 'en', 'Right-wing commentator Milo Yiannopoulos detained by ICE', 'https://www.bbc.co.uk/news/articles/cj06jgq62v9o', 'The British citizen, who lives and works in the US, has supported Trump and ICE agents in the past.', 'https://ichef.bbci.co.uk/ace/standard/240/cpsprodpb/e120/live/d58e6a30-a31f-11f1-92a5-fbd6f5289e6b.jpg', '2026-08-28T21:01:39+00:00', '2026-08-29T00:03:08.501764'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (427267, 16336, 'The Guardian', 'en', 'Milo Yiannopoulos, a far-right political commentator, detained by ICE', 'https://www.theguardian.com/us-news/2026/aug/28/milo-yiannopoulos-detained-ice', 'A former editor of Breitbart News, Yiannopoulos has also served as an intern for Marjorie Taylor Greene Milo Yiannopoulos, a far-right British political commentator, was detained by Immigration and Customs Enforcement in Louisiana, according to the Department of Homeland Security (DHS). In a statement on Friday, a DHS spokesperson said that Yiannopoulos was arrested on Thursday at the Louis Armstrong New Orleans international airport (MSY). The spokesperson said Yiannopoulos “legally entered the country” in May 2019, but that “he chose to overstay his welcome in violation of our nation’s laws”', 'https://i.guim.co.uk/img/media/fd4f1b840dd01b597ddcd90c5994515f1cf0d76b/250_0_2500_2000/master/2500.jpg?width=140&quality=85&auto=format&fit=max&s=4302fa00ed9b3df2a312c2209b82b17b', '2026-08-28T21:13:39+00:00', '2026-08-29T00:03:20.592138'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
